+<body>
+<h1>Grok 4.7</h1>
+<div class="status" id="status">Armed</div>
+<canvas id="view"></canvas>
+<aside class="panel">
+  <h2>Experiment settings</h2>
+  <label class="row"><span>Car speed</span><b id="labSpeed">22 m/s</b></label>
