+  <label class="row"><span>Brick mass</span><b id="labMass">2.5 kg</b></label>
+  <input id="inMass" type="range" min="0.5" max="12" step="0.1" value="2.5">
+  <div class="constants">
+    <div>Gravity <b>9.81</b></div>
