+    <div>Brick e <b>0.18</b></div>
+    <div>Ground μ <b>0.85</b></div>
+    <div>Car mass <b>1250 kg</b></div>
+    <div>Car size <b>4.2×1.45 m</b></div>
+    <div>Brick size <b>0.50×0.24 m</b></div>
+    <div>Scale <b>80 px/m</b></div>
+  </div>
+</aside>
+<div class="hud">
+  <div class="stat"><em>Car speed</em><strong id="telSpeed">0.00</strong></div>
+  <div class="stat"><em>Elapsed</em><strong id="telTime">0.00 s</strong></div>
+  <div class="stat"><em>Moving bricks</em><strong id="telMove">0</strong></div>
+  <div class="stat"><em>Impact speed</em><strong id="telImpact">—</strong></div>
+</div>
+<div class="scalebar"><i></i>1 m · 80 px</div>
