+</div>
+<script>
+"use strict";
+
+const SCALE = 80;
+const GRAVITY = 9.81;
+const BRICK_FRICTION = 0.72;
+const BRICK_RESTITUTION = 0.18;
+const GROUND_FRICTION = 0.85;
+const CAR_MASS = 1250;
+const CAR_L = 4.2;
+const CAR_H = 1.45;
+const CAR_W = 1.9;
+const BRICK_L = 0.5;
+const BRICK_H = 0.24;
+const YAW = 0.62;
+const COS = Math.cos(YAW);
+const SIN = Math.sin(YAW);
+const Z_LIFT = 0.2;
+const RUNWAY = 7.2;
+const SLOP = 0.0035;
+const REST_THRESH = 0.45;
+
+const PALETTE = ["#a34432", "#b5523c", "#8d3a2e", "#c46245", "#7a332b", "#9a4636", "#b86a48", "#6e2e28"];
+
+const canvas = document.getElementById("view");
+const ctx = canvas.getContext("2d");
+
+const ui = {
+  speed: document.getElementById("inSpeed"),
+  cols: document.getElementById("inCols"),
+  rows: document.getElementById("inRows"),
+  layers: document.getElementById("inLayers"),
+  mass: document.getElementById("inMass"),
+  labSpeed: document.getElementById("labSpeed"),
+  labCols: document.getElementById("labCols"),
+  labRows: document.getElementById("labRows"),
+  labLayers: document.getElementById("labLayers"),
+  labMass: document.getElementById("labMass"),
+  telSpeed: document.getElementById("telSpeed"),
+  telTime: document.getElementById("telTime"),
+  telMove: document.getElementById("telMove"),
+  telImpact: document.getElementById("telImpact"),
+  status: document.getElementById("status"),
+  test: document.getElementById("testBtn"),
+  reset: document.getElementById("resetBtn"),
+};
+
+let viewW = 1280, viewH = 720, groundScreen = 560, dpr = 1;
+let camX = 0, camShake = 0, shakeT = 0;
+let bodies = [];
+let car = null;
+let wallFaceX = 0;
+let brickCount = 0;
+let particles = [];
+let skids = [];
+let impulseCache = new Map();
+let applied = readSettings();
+let phase = "armed";
+let simTime = 0;
+let impactSpeed = null;
+let driving = false;
+let crumple = 0;
+let lastImpact = 0;
+let acc = 0;
+let lastNow = 0;
+let supportTick = 0;
+
+function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
+function readSettings() {
+  return {
+    speed: clamp(+ui.speed.value, 5, 45),
+    columns: clamp(ui.cols.value | 0, 4, 24),
+    rows: clamp(ui.rows.value | 0, 3, 16),
+    layers: clamp(ui.layers.value | 0, 1, 5),
+    mass: clamp(+ui.mass.value, 0.5, 12),
+  };
+}
+function syncLabels() {
+  const s = readSettings();
+  ui.labSpeed.textContent = s.speed.toFixed(0) + " m/s";
+  ui.labCols.textContent = String(s.columns);
+  ui.labRows.textContent = String(s.rows);
+  ui.labLayers.textContent = String(s.layers);
+  ui.labMass.textContent = s.mass.toFixed(1) + " kg";
+  const dirty = s.speed !== applied.speed || s.columns !== applied.columns || s.rows !== applied.rows || s.layers !== applied.layers || Math.abs(s.mass - applied.mass) > 1e-9;
+  ui.test.classList.toggle("dirty", dirty && phase !== "armed");
+}
+
+function makeBody(opts) {
+  const w = opts.w, h = opts.h, d = opts.d;
+  const mass = opts.mass;
+  const invMass = opts.fixed ? 0 : 1 / mass;
+  const inertia = opts.fixed ? 0 : mass * (w * w + h * h) / 12;
+  return {
+    id: opts.id,
+    type: opts.type,
+    x: opts.x, y: opts.y, z: opts.z,
+    a: 0,
+    vx: 0, vy: 0, vz: 0, w: 0,
+    hx: w / 2, hy: h / 2, hz: d / 2,
+    mass, invMass,
+    invI: inertia > 0 ? 1 / inertia : 0,
+    sleeping: true,
+    sleepT: 0,
+    color: opts.color || "#888",
+    rad: Math.hypot(w / 2, h / 2) + 0.02,
+    onGround: false,
+  };
+}
+
+function buildWorld(launch) {
+  applied = readSettings();
+  ui.speed.value = String(applied.speed);
+  ui.cols.value = String(applied.columns);
+  ui.rows.value = String(applied.rows);
+  ui.layers.value = String(applied.layers);
+  ui.mass.value = String(applied.mass);
+  syncLabels();
+
+  bodies = [];
+  particles = [];
+  skids = [];
+  impulseCache = new Map();
+  simTime = 0;
+  impactSpeed = null;
+  crumple = 0;
+  camShake = 0;
+  acc = 0;
+  driving = !!launch;
+  phase = launch ? "run" : "armed";
+
+  const carX = 1.15 + CAR_L / 2;
+  wallFaceX = carX + CAR_L / 2 + RUNWAY;
+
+  car = makeBody({
+    id: 1,
+    type: "car",
+    x: carX,
+    y: CAR_H / 2,
+    z: 0,
+    w: CAR_L,
+    h: CAR_H,
+    d: CAR_W,
+    mass: CAR_MASS,
+    fixed: false,
+    color: "#d8dee6",
+  });
+  car.sleeping = !launch;
+  bodies.push(car);
+
+  const cols = applied.columns;
+  const rows = applied.rows;
+  const layers = applied.layers;
+  const extra = BRICK_L * 0.5;
+  const totalZ = cols * BRICK_L + extra;
+  const z0 = -totalZ / 2;
+  let id = 2;
+  for (let layer = 0; layer < layers; layer++) {
+    for (let row = 0; row < rows; row++) {
+      const rowOff = (row % 2) * extra;
+      const layerOff = (layer % 2) * extra;
+      for (let col = 0; col < cols; col++) {
+        const z = z0 + rowOff + layerOff + (col + 0.5) * BRICK_L;
+        const y = (row + 0.5) * BRICK_H;
+        const x = wallFaceX + (layer + 0.5) * BRICK_L;
+        const color = PALETTE[(layer * 5 + row * 3 + col) % PALETTE.length];
+        bodies.push(makeBody({
+          id: id++,
+          type: "brick",
+          x, y, z,
+          w: BRICK_L,
+          h: BRICK_H,
+          d: BRICK_L,
+          mass: applied.mass,
+          color,
+        }));
+      }
+    }
+  }
+  brickCount = bodies.length - 1;
+  frameCamera(1);
+}
+
+function carNoseX() {
+  const c = Math.cos(car.a), s = Math.sin(car.a);
+  return car.x + car.hx * c;
+}
+
+function applyDrive(dt) {
+  const dist = Math.max(0.04, wallFaceX - carNoseX());
+  const tgt = applied.speed;
+  const v = car.vx;
+  if (v >= tgt - 1e-4) {
+    car.vx = tgt;
+    return;
+  }
+  const accel = clamp((tgt * tgt - v * v) / (2 * dist), 0, 220);
+  car.vx = Math.min(tgt, v + accel * dt);
+}
+
+function corners2d(b) {
+  const c = Math.cos(b.a), s = Math.sin(b.a);
+  const hx = b.hx, hy = b.hy;
+  const locs = [[-hx, -hy], [hx, -hy], [hx, hy], [-hx, hy]];
+  const out = new Array(4);
+  for (let i = 0; i < 4; i++) {
+    const lx = locs[i][0], ly = locs[i][1];
+    out[i] = [b.x + lx * c - ly * s, b.y + lx * s + ly * c];
+  }
+  return out;
+}
+
+function sat2d(a, b, pa, pb) {
+  let best = Infinity, nx = 0, ny = 1;
+  for (let pass = 0; pass < 2; pass++) {
+    const pts = pass === 0 ? pa : pb;
+    for (let i = 0; i < 4; i++) {
+      const p1 = pts[i], p2 = pts[(i + 1) % 4];
+      let ax = -(p2[1] - p1[1]);
+      let ay = p2[0] - p1[0];
+      const len = Math.hypot(ax, ay) || 1;
+      ax /= len; ay /= len;
+      let amin = Infinity, amax = -Infinity, bmin = Infinity, bmax = -Infinity;
+      for (let k = 0; k < 4; k++) {
+        const da = pa[k][0] * ax + pa[k][1] * ay;
+        const db = pb[k][0] * ax + pb[k][1] * ay;
+        if (da < amin) amin = da;
+        if (da > amax) amax = da;
+        if (db < bmin) bmin = db;
+        if (db > bmax) bmax = db;
+      }
+      const overlap = Math.min(amax, bmax) - Math.max(amin, bmin);
+      if (overlap <= 0) return null;
+      if (overlap < best) {
+        best = overlap;
+        if ((b.x - a.x) * ax + (b.y - a.y) * ay < 0) { ax = -ax; ay = -ay; }
+        nx = ax; ny = ay;
+      }
+    }
+  }
+  return { pen: best, nx, ny };
+}
+
+function pointInOBB(b, x, y, margin) {
+  const dx = x - b.x, dy = y - b.y;
+  const c = Math.cos(b.a), s = Math.sin(b.a);
+  const lx = dx * c + dy * s;
+  const ly = -dx * s + dy * c;
+  return Math.abs(lx) <= b.hx + margin && Math.abs(ly) <= b.hy + margin;
+}
+
+function incidentPoints(host, other, nx, ny, pa, pb) {
+  const pts = other === bRef(other, pb) ? pb : pb;
+  const scored = pts.map((p) => ({ p, d: p[0] * nx + p[1] * ny }));
+  scored.sort((u, v) => u.d - v.d);
+  const picked = [];
+  for (let i = 0; i < 2; i++) {
+    const p = scored[i].p;
+    if (pointInOBB(host, p[0], p[1], 0.03)) picked.push(p);
+  }
+  if (!picked.length) {
+    const p = scored[0].p;
+    picked.push(p);
+  }
+  return picked;
+}
+
+function bRef() { return null; }
+
+function collidePair(a, b) {
+  const zPen = a.hz + b.hz - Math.abs(b.z - a.z);
+  if (zPen < -0.0008) return null;
+  const pa = corners2d(a);
+  const pb = corners2d(b);
+  const sat = sat2d(a, b, pa, pb);
+  if (!sat) return null;
+
+  if (zPen < sat.pen) {
+    const nz = b.z >= a.z ? 1 : -1;
+    return {
+      a, b,
+      nx: 0, ny: 0, nz,
+      pen: Math.max(0, zPen),
+      points: [{
+        x: (a.x + b.x) * 0.5,
+        y: (a.y + b.y) * 0.5,
+        z: nz > 0 ? a.z + a.hz : a.z - a.hz,
+        jn: 0, j1: 0, j2: 0,
+      }],
+    };
+  }
+
+  const hostIsA = Math.abs((b.x - a.x) * sat.nx + (b.y - a.y) * sat.ny) >= 0;
+  const incident = incidentPoints(a, b, sat.nx, sat.ny, pa, pb);
+  const zMid = clamp((a.z + b.z) * 0.5, Math.max(a.z - a.hz, b.z - b.hz), Math.min(a.z + a.hz, b.z + b.hz));
+  const points = [];
+  for (let i = 0; i < incident.length; i++) {
+    points.push({ x: incident[i][0], y: incident[i][1], z: zMid, jn: 0, j1: 0, j2: 0 });
+  }
+  if (!hostIsA) { /* normal already A to B */ }
+  return { a, b, nx: sat.nx, ny: sat.ny, nz: 0, pen: sat.pen, points };
+}
+
+function materials(a, b) {
+  const types = a.type + b.type;
+  const ground = a.type === "ground" || b.type === "ground";
+  const carHit = a.type === "car" || b.type === "car";
+  if (ground && carHit) return { mu: driving ? 0.02 : GROUND_FRICTION, e: 0.05 };
+  if (ground) return { mu: GROUND_FRICTION, e: BRICK_RESTITUTION };
+  return { mu: BRICK_FRICTION, e: BRICK_RESTITUTION };
+}
+
+function cellKey(ix, iy) { return ix + "," + iy; }
+
+function buildHash() {
+  const map = new Map();
+  const inv = 1 / 0.55;
+  for (let i = 0; i < bodies.length; i++) {
+    const b = bodies[i];
+    const r = b.rad;
+    const x0 = Math.floor((b.x - r) * inv);
+    const x1 = Math.floor((b.x + r) * inv);
+    const y0 = Math.floor((b.y - r) * inv);
+    const y1 = Math.floor((b.y + r) * inv);
+    for (let ix = x0; ix <= x1; ix++) {
+      for (let iy = y0; iy <= y1; iy++) {
+        const k = cellKey(ix, iy);
+        let bucket = map.get(k);
+        if (!bucket) { bucket = []; map.set(k, bucket); }
+        bucket.push(b);
+      }
+    }
+  }
+  return map;
+}
+
+function findContacts() {
+  const hash = buildHash();
+  const seen = new Set();
+  const contacts = [];
+  const inv = 1 / 0.55;
+
+  for (let i = 0; i < bodies.length; i++) {
+    const a = bodies[i];
+    if (a.sleeping && a !== car) continue;
+    const r = a.rad;
+    const x0 = Math.floor((a.x - r) * inv) - 1;
+    const x1 = Math.floor((a.x + r) * inv) + 1;
+    const y0 = Math.floor((a.y - r) * inv) - 1;
+    const y1 = Math.floor((a.y + r) * inv) + 1;
+    const mine = new Set();
+    for (let ix = x0; ix <= x1; ix++) {
+      for (let iy = y0; iy <= y1; iy++) {
+        const bucket = hash.get(cellKey(ix, iy));
+        if (!bucket) continue;
+        for (let k = 0; k < bucket.length; k++) mine.add(bucket[k]);
+      }
+    }
+    mine.forEach((b) => {
+      if (b === a || (a.sleeping && b.sleeping)) return;
+      const id1 = a.id < b.id ? a.id : b.id;
+      const id2 = a.id < b.id ? b.id : a.id;
+      const key = id1 + ":" + id2;
