+  ui.rows.addEventListener(ev, syncLabels);
+  ui.layers.addEventListener(ev, syncLabels);
+  ui.mass.addEventListener(ev, syncLabels);
+});
+
+ui.test.addEventListener("click", () => buildWorld(true));
+ui.reset.addEventListener("click", () => buildWorld(false));
+window.addEventListener("keydown", (e) => {
+  if (e.target && (e.target.tagName === "INPUT" || e.target.tagName === "TEXTAREA")) return;
