function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
function readSettings() {
  return {
    speed: clamp(+ui.speed.value, 5, 45),
    columns: clamp(ui.cols.value | 0, 4, 24),
    rows: clamp(ui.rows.value | 0, 3, 16),
    layers: clamp(ui.layers.value | 0, 1, 5),
    mass: clamp(+ui.mass.value, 0.5, 12),
  };
}
function syncLabels() {
  const s = readSettings();
  ui.labSpeed.textContent = s.speed.toFixed(0) + " m/s";
  ui.labCols.textContent = String(s.columns);
  ui.labRows.textContent = String(s.rows);
  ui.labLayers.textContent = String(s.layers);
  ui.labMass.textContent = s.mass.toFixed(1) + " kg";
  const dirty = s.speed !== applied.speed || s.columns !== applied.columns || s.rows !== applied.rows || s.layers !== applied.layers || Math.abs(s.mass - applied.mass) > 1e-9;
