}

function makeBody(opts) {
  const w = opts.w, h = opts.h, d = opts.d;
  const mass = opts.mass;
  const invMass = opts.fixed ? 0 : 1 / mass;
  const inertia = opts.fixed ? 0 : mass * (w * w + h * h) / 12;
  return {
    id: opts.id,
    type: opts.type,
    x: opts.x, y: opts.y, z: opts.z,
    a: 0,
    vx: 0, vy: 0, vz: 0, w: 0,
