      for (let k = 0; k < 4; k++) {
        const da = pa[k][0] * ax + pa[k][1] * ay;
        const db = pb[k][0] * ax + pb[k][1] * ay;
        if (da < amin) amin = da;
        if (da > amax) amax = da;
        if (db < bmin) bmin = db;
        if (db > bmax) bmax = db;
      }
      const overlap = Math.min(amax, bmax) - Math.max(amin, bmin);
      if (overlap <= 0) return null;
      if (overlap < best) {
