function velAt(b, px, py) {
  const rx = px - b.x, ry = py - b.y;
  return [b.vx - b.w * ry, b.vy + b.w * rx, b.vz, rx, ry];
}

function applyJ(b, jx, jy, jz, rx, ry) {
