      const djt = jt - p[store];
      p[store] = jt;
      applyJ(a, -djt * tx, -djt * ty, -djt * tz, rAx, rAy);
      if (b) applyJ(b, djt * tx, djt * ty, djt * tz, rBx, rBy);
    }
  }
  const mag = maxJ;
  if (mag > 0.04) {
    wake(a, mag);
    wake(b, mag);
    const brick = a.type === "brick" ? a : (b && b.type === "brick" ? b : null);
    const hitCar = a.type === "car" || (b && b.type === "car");
    if (hitCar && brick) {
      if (mag > lastImpact) lastImpact = mag;
      if (driving) {
        driving = false;
        if (impactSpeed == null) impactSpeed = Math.hypot(car.vx, car.vy, car.vz);
      }
      if (mag > 8 && !m._dusted) {
        m._dusted = true;
        camShake = Math.min(16, camShake + mag * 0.00045);
        crumple = Math.min(0.42, crumple + mag * 0.0000025);
        spawnDust(m, mag);
      }
    }
  }
  return mag;
}

function correctPositions(contacts) {
  for (let i = 0; i < contacts.length; i++) {
    const m = contacts[i];
    const pen = m.pen - SLOP;
    if (pen <= 0) continue;
    const a = m.a, b = m.b;
    const inv = a.invMass + (b ? b.invMass : 0);
    if (inv <= 0) continue;
    const percent = pen > 0.06 ? 0.95 : 0.7;
    const c = pen * percent / inv;
    a.x -= m.nx * c * a.invMass;
    a.y -= m.ny * c * a.invMass;
    a.z -= m.nz * c * a.invMass;
    if (b) {
      b.x += m.nx * c * b.invMass;
      b.y += m.ny * c * b.invMass;
      b.z += m.nz * c * b.invMass;
    } else if (m.ground) {
      if (a.y - a.hy < 0 && Math.abs(a.a) < 0.04) a.y -= (a.y - a.hy);
      const pts = corners2d(a);
      let lowest = Infinity;
      for (let p = 0; p < 4; p++) if (pts[p][1] < lowest) lowest = pts[p][1];
      if (lowest < 0) {
        a.y -= lowest;
        if (a.vy < 0) a.vy = 0;
      }
    }
  }
}

function storeCache(contacts) {
  impulseCache = new Map();
  for (let i = 0; i < contacts.length; i++) {
    const m = contacts[i];
    const base = (m.b ? Math.min(m.a.id, m.b.id) + ":" + Math.max(m.a.id, m.b.id) : "g" + m.a.id);
    for (let p = 0; p < m.points.length; p++) {
      const pt = m.points[p];
      impulseCache.set(base + ":" + p, { jn: pt.jn * 0.85, j1: pt.j1 * 0.7, j2: pt.j2 * 0.7 });
    }
  }
}

function bodySupported(b) {
  const pts = corners2d(b);
  let minY = Infinity;
  for (let i = 0; i < 4; i++) if (pts[i][1] < minY) minY = pts[i][1];
  if (minY <= 0.03) return true;
  for (let i = 0; i < bodies.length; i++) {
    const o = bodies[i];
    if (o === b) continue;
    if (Math.abs(o.z - b.z) > b.hz + o.hz - 0.008) continue;
    if (Math.abs(o.x - b.x) > b.hx + o.hx - 0.008) continue;
    if (o.y >= b.y) continue;
    const op = corners2d(o);
    let maxY = -Infinity;
    for (let k = 0; k < 4; k++) if (op[k][1] > maxY) maxY = op[k][1];
    if (maxY >= minY - 0.025 && maxY <= minY + 0.05) return true;
  }
  return false;
}

function clampMotion(b) {
  const sp = Math.hypot(b.vx, b.vy, b.vz);
  const cap = b.type === "car" ? 70 : 55;
  if (sp > cap) {
    const s = cap / sp;
    b.vx *= s; b.vy *= s; b.vz *= s;
  }
  if (b.w > 28) b.w = 28;
  if (b.w < -28) b.w = -28;
}

function substep(dt) {
  if (driving) {
    if (carNoseX() >= wallFaceX - 0.01) {
      driving = false;
      if (impactSpeed == null) impactSpeed = Math.hypot(car.vx, car.vy, car.vz);
    } else {
      applyDrive(dt);
    }
  }

  for (let i = 0; i < bodies.length; i++) {
    const b = bodies[i];
    if (b.sleeping) continue;
    b.vy -= GRAVITY * dt;
    b.w *= 1 - 0.06 * dt;
    b.x += b.vx * dt;
    b.y += b.vy * dt;
    b.z += b.vz * dt;
    b.a += b.w * dt;
    clampMotion(b);
  }

  const contacts = findContacts();
  const iters = bodies.length > 900 ? 8 : 12;
  for (let iter = 0; iter < iters; iter++) {
    for (let i = 0; i < contacts.length; i++) solveContact(contacts[i], dt, iter === 0);
  }
  correctPositions(contacts);
  storeCache(contacts);

  supportTick++;
  const doSupport = supportTick % (bodies.length > 900 ? 3 : 1) === 0;
  for (let i = 0; i < bodies.length; i++) {
    const b = bodies[i];
    if (b.type === "car") {
      const sp = Math.hypot(b.vx, b.vy, b.vz);
      if (!driving && sp < 0.12 && Math.abs(b.w) < 0.15 && b.onGround) {
        b.sleepT += dt;
        if (b.sleepT > 0.45) {
          b.sleeping = true;
          b.vx = b.vy = b.vz = b.w = 0;
        }
      } else b.sleepT = 0;
      continue;
    }
    if (b.sleeping) {
      if (doSupport && !bodySupported(b)) {
        b.sleeping = false;
        b.sleepT = 0;
      }
      continue;
    }
    const sp = Math.hypot(b.vx, b.vy, b.vz);
    if (sp < 0.07 && Math.abs(b.w) < 0.12) {
      b.sleepT += dt;
      if (b.sleepT > 0.32 && bodySupported(b)) {
        b.sleeping = true;
        b.vx = b.vy = b.vz = b.w = 0;
      }
    } else b.sleepT = 0;
  }

  if (driving && car.onGround && Math.abs(car.vx) > 1) dropSkid();
  if (!driving && car.onGround && Math.abs(car.vx) > 1.2) dropSkid();
}

function dropSkid() {
  const c = Math.cos(car.a), s = Math.sin(car.a);
  const axles = [-1.35, 1.28];
  for (let i = 0; i < axles.length; i++) {
    const lx = axles[i];
    const ly = -CAR_H / 2 + 0.34;
    skids.push({
      x: car.x + lx * c - ly * s,
      y: 0.01,
      z: car.z,
      life: 1,
    });
  }
  if (skids.length > 500) skids.splice(0, skids.length - 500);
}

function spawnDust(m, mag) {
  const p = m.points[0];
  const n = mag > 40 ? 7 : 4;
  for (let i = 0; i < n; i++) {
    if (particles.length > 420) particles.shift();
    const spread = (i - (n - 1) / 2) * 0.55;
    particles.push({
      x: p.x,
      y: Math.max(0.05, p.y),
      z: p.z + spread * 0.08,
      vx: m.nx * (1.2 + i * 0.15) + spread * 0.8 + (m.a.vx || 0) * 0.15,
      vy: Math.abs(m.ny) * 1.4 + 0.8 + i * 0.18,
      vz: m.nz * 1.1 + spread,
      life: 0.55 + (i % 3) * 0.12,
      age: 0,
      r: 0.035 + (i % 4) * 0.012,
    });
  }
}

function updateVisuals(dt) {
  camShake *= Math.exp(-dt * 5.5);
  shakeT += dt;
  crumple *= Math.exp(-dt * 0.35);
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.age += dt;
    if (p.age > p.life) { particles.splice(i, 1); continue; }
    p.vy -= GRAVITY * 0.35 * dt;
    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.z += p.vz * dt;
    if (p.y < 0.02) { p.y = 0.02; p.vy *= -0.2; p.vx *= 0.8; }
  }
}

function resize() {
  dpr = Math.min(window.devicePixelRatio || 1, 2);
  viewW = window.innerWidth;
  viewH = window.innerHeight;
  canvas.width = Math.floor(viewW * dpr);
  canvas.height = Math.floor(viewH * dpr);
  canvas.style.width = viewW + "px";
  canvas.style.height = viewH + "px";
  groundScreen = viewH * 0.78;
}

function project(x, y, z) {
  const sx = (x - camX) * COS * SCALE + z * SIN * SCALE + viewW * 0.34;
  const sy = groundScreen - y * SCALE - z * SIN * SCALE * Z_LIFT;
  return [sx, sy];
}

function frameCamera(alpha) {
  const focus = phase === "run" ? car.x + 1.1 : (car.x * 0.35 + wallFaceX * 0.65);
  const target = focus - (viewW * 0.34) / (COS * SCALE) + viewW * 0.08 / (COS * SCALE);
  camX += (target - camX) * alpha;
}

function worldToScreen(x, y, z) {
  const sh = camShake;
  const ox = sh ? Math.sin(shakeT * 47) * sh : 0;
  const oy = sh ? Math.cos(shakeT * 39) * sh * 0.65 : 0;
  const p = project(x, y, z);
  return [p[0] + ox, p[1] + oy];
}

function shade(hex, f) {
  const n = parseInt(hex.slice(1), 16);
  let r = ((n >> 16) & 255) * f;
  let g = ((n >> 8) & 255) * f;
  let b = (n & 255) * f;
  r = r > 255 ? 255 : r; g = g > 255 ? 255 : g; b = b > 255 ? 255 : b;
  return "rgb(" + (r | 0) + "," + (g | 0) + "," + (b | 0) + ")";
}

function localPoint(b, lx, ly, lz) {
  const c = Math.cos(b.a), s = Math.sin(b.a);
  return [b.x + lx * c - ly * s, b.y + lx * s + ly * c, b.z + lz];
}

function drawGround() {
  const x0 = camX - 6, x1 = camX + viewW / (SCALE * COS) + 10;
  const z0 = -14, z1 = 14;
  const g0 = worldToScreen(x0, 0, z0);
  const g1 = worldToScreen(x1, 0, z0);
  const g2 = worldToScreen(x1, 0, z1);
  const g3 = worldToScreen(x0, 0, z1);
  ctx.beginPath();
  ctx.moveTo(g0[0], g0[1]);
  ctx.lineTo(g1[0], g1[1]);
  ctx.lineTo(g2[0], g2[1]);
  ctx.lineTo(g3[0], g3[1]);
  ctx.closePath();
  const grd = ctx.createLinearGradient(0, groundScreen - 40, 0, viewH);
  grd.addColorStop(0, "#4a515b");
  grd.addColorStop(0.18, "#3c424b");
  grd.addColorStop(1, "#2a3038");
  ctx.fillStyle = grd;
  ctx.fill();

  ctx.beginPath();
  ctx.moveTo(0, groundScreen + 8);
  ctx.lineTo(viewW, groundScreen + 8);
  ctx.lineTo(viewW, viewH);
  ctx.lineTo(0, viewH);
  ctx.fillStyle = "#23282f";
  ctx.fill();

  ctx.strokeStyle = "rgba(255,255,255,0.16)";
  ctx.lineWidth = 2;
  ctx.beginPath();
  const horizonL = worldToScreen(x0, 0, -3.2);
  const horizonR = worldToScreen(x1, 0, -3.2);
  ctx.moveTo(horizonL[0], horizonL[1]);
  ctx.lineTo(horizonR[0], horizonR[1]);
  ctx.stroke();

  ctx.strokeStyle = "rgba(240,162,2,0.85)";
  ctx.lineWidth = 3;
  ctx.setLineDash([18, 16]);
  const laneA = worldToScreen(x0, 0.01, 0);
  const laneB = worldToScreen(x1, 0.01, 0);
  ctx.beginPath();
  ctx.moveTo(laneA[0], laneA[1]);
  ctx.lineTo(laneB[0], laneB[1]);
  ctx.stroke();
  ctx.setLineDash([]);

  ctx.fillStyle = "rgba(255,255,255,0.55)";
  ctx.font = "11px ui-monospace, Menlo, monospace";
  ctx.textAlign = "center";
  const start = Math.floor(x0);
  for (let x = start; x < x1; x += 1) {
    const p = worldToScreen(x, 0, 0);
    if (p[0] < -20 || p[0] > viewW + 20) continue;
    ctx.fillRect(p[0], p[1], 1.5, 8);
    if (x % 2 === 0) ctx.fillText(x + " m", p[0], p[1] + 20);
  }

  for (let i = 0; i < skids.length; i++) {
    const s = skids[i];
    const p = worldToScreen(s.x, 0.012, s.z);
    ctx.fillStyle = "rgba(20,20,22,0.45)";
    ctx.fillRect(p[0], p[1], 10, 3);
  }
}

function drawBrick(b) {
  const inset = 0.008;
  const hx = b.hx - inset, hy = b.hy - inset, hz = b.hz - inset * 0.5;
  const corners = [
    localPoint(b, -hx, -hy, -hz),
    localPoint(b, hx, -hy, -hz),
    localPoint(b, hx, hy, -hz),
    localPoint(b, -hx, hy, -hz),
    localPoint(b, -hx, -hy, hz),
    localPoint(b, hx, -hy, hz),
    localPoint(b, hx, hy, hz),
    localPoint(b, -hx, hy, hz),
  ];
  const faces = [
    { idx: [0, 3, 2, 1], n: localNormal(b, -1, 0, 0) },
    { idx: [4, 5, 6, 7], n: localNormal(b, 1, 0, 0) },
    { idx: [0, 1, 5, 4], n: localNormal(b, 0, -1, 0) },
    { idx: [3, 7, 6, 2], n: localNormal(b, 0, 1, 0) },
    { idx: [0, 4, 7, 3], n: localNormal(b, 0, 0, -1) },
    { idx: [1, 2, 6, 5], n: localNormal(b, 0, 0, 1) },
  ];
  const toward = [SIN, 0.15, -COS];
  const light = [-0.25, 0.86, 0.28];
  const drawFaces = [];
  for (let i = 0; i < faces.length; i++) {
    const f = faces[i];
    const nd = f.n[0] * toward[0] + f.n[1] * toward[1] + f.n[2] * toward[2];
    if (nd <= 0.02) continue;
    const ld = f.n[0] * light[0] + f.n[1] * light[1] + f.n[2] * light[2];
    let depth = 0;
    for (let k = 0; k < 4; k++) {
      const c = corners[f.idx[k]];
      depth += -c[0] * SIN + c[2] * COS;
    }
    drawFaces.push({ f, shade: 0.48 + 0.62 * Math.max(0, ld), depth, nd });
  }
  drawFaces.sort((u, v) => v.depth - u.depth);
  for (let i = 0; i < drawFaces.length; i++) {
    const f = drawFaces[i].f;
    ctx.beginPath();
    for (let k = 0; k < 4; k++) {
      const c = corners[f.idx[k]];
      const s = worldToScreen(c[0], c[1], c[2]);
      if (k === 0) ctx.moveTo(s[0], s[1]);
      else ctx.lineTo(s[0], s[1]);
    }
    ctx.closePath();
    ctx.fillStyle = shade(b.color, drawFaces[i].shade);
    ctx.fill();
    ctx.strokeStyle = "rgba(40,16,12,0.45)";
    ctx.lineWidth = 1;
    ctx.stroke();
  }
}

function localNormal(b, lx, ly, lz) {
  const c = Math.cos(b.a), s = Math.sin(b.a);
  return [lx * c - ly * s, lx * s + ly * c, lz];
}

function drawWheel(x, y, z, radius, spin) {
  const c = worldToScreen(x, y, z);
  const rx = radius * SCALE * (0.55 * SIN + 0.72 * COS);
  const ry = radius * SCALE;
  ctx.save();
  ctx.translate(c[0], c[1]);
  ctx.beginPath();
  ctx.ellipse(0, 0, Math.max(6, rx), Math.max(6, ry), 0, 0, Math.PI * 2);
  ctx.fillStyle = "#1b1e24";
  ctx.fill();
  ctx.strokeStyle = "#4d5560";
  ctx.lineWidth = 2;
  ctx.stroke();
  ctx.beginPath();
  ctx.ellipse(0, 0, Math.max(3, rx * 0.45), Math.max(3, ry * 0.45), 0, 0, Math.PI * 2);
  ctx.fillStyle = "#c5ccd4";
  ctx.fill();
  ctx.beginPath();
  const ang = spin;
  ctx.strokeStyle = "#2a3038";
  ctx.lineWidth = 1.5;
  for (let i = 0; i < 3; i++) {
    const t = ang + i * Math.PI / 3;
    ctx.moveTo(Math.cos(t) * 2, Math.sin(t) * 2);
    ctx.lineTo(Math.cos(t) * rx * 0.42, Math.sin(t) * ry * 0.42);
  }
  ctx.stroke();
  ctx.restore();
}

function drawCar() {
  const nose = crumple;
  const c = Math.cos(car.a), s = Math.sin(car.a);
  function L(lx, ly, lz) {
    const wx = car.x + lx * c - ly * s;
    const wy = car.y + lx * s + ly * c;
    return worldToScreen(wx, wy, car.z + lz);
  }
  const hz = car.hz;
  const silhouette = [
    [-2.08, -0.62],
    [-2.02, -0.28],
    [-1.72, -0.18],
    [-1.25, 0.02],
    [-0.72, 0.22],
    [-0.35, 0.48],
    [0.15, 0.62],
    [0.72, 0.58],
    [1.05, 0.28],
    [1.48, 0.08],
    [1.92 - nose, -0.02],
    [2.08 - nose, -0.22],
    [2.02 - nose, -0.55],
    [1.55, -0.62],
    [0.95, -0.62],
    [0.72, -0.5],
    [-0.15, -0.5],
    [-0.55, -0.62],
    [-1.15, -0.62],
    [-1.55, -0.5],
  ];

  function pathSide(z, shift) {
    ctx.beginPath();
    for (let i = 0; i < silhouette.length; i++) {
      const p = L(silhouette[i][0] + shift, silhouette[i][1], z);
      if (i === 0) ctx.moveTo(p[0], p[1]);
      else ctx.lineTo(p[0], p[1]);
    }
    ctx.closePath();
  }

  pathSide(hz, 0);
  ctx.fillStyle = "#9aa3ad";
  ctx.fill();

  const roofA = L(-0.35, 0.48, -hz);
  const roofB = L(0.72, 0.58, -hz);
  const roofC = L(0.72, 0.58, hz);
  const roofD = L(-0.35, 0.48, hz);
  ctx.beginPath();
  ctx.moveTo(roofA[0], roofA[1]);
  ctx.lineTo(roofB[0], roofB[1]);
  ctx.lineTo(roofC[0], roofC[1]);
  ctx.lineTo(roofD[0], roofD[1]);
  ctx.closePath();
  ctx.fillStyle = "#c5ced6";
  ctx.fill();

  const hoodA = L(1.05, 0.28, -hz);
  const hoodB = L(2.05 - nose, -0.08, -hz);
  const hoodC = L(2.05 - nose, -0.08, hz);
  const hoodD = L(1.05, 0.28, hz);
  ctx.beginPath();
  ctx.moveTo(hoodA[0], hoodA[1]);
  ctx.lineTo(hoodB[0], hoodB[1]);
  ctx.lineTo(hoodC[0], hoodC[1]);
  ctx.lineTo(hoodD[0], hoodD[1]);
  ctx.closePath();
  ctx.fillStyle = "#d5dde4";
  ctx.fill();

  pathSide(-hz, 0);
  ctx.fillStyle = "#d7dee6";
  ctx.fill();
  ctx.strokeStyle = "#2c3440";
  ctx.lineWidth = 1.4;
  ctx.stroke();

  ctx.beginPath();
  const win = [[-0.28, 0.18], [0.05, 0.5], [0.62, 0.48], [0.95, 0.2]];
  for (let i = 0; i < win.length; i++) {
    const p = L(win[i][0], win[i][1], -hz - 0.01);
    if (i === 0) ctx.moveTo(p[0], p[1]);
    else ctx.lineTo(p[0], p[1]);
  }
  ctx.closePath();
  ctx.fillStyle = "rgba(70, 110, 130, 0.88)";
  ctx.fill();

  ctx.beginPath();
  const doorA = L(-0.15, -0.08, -hz - 0.012);
  const doorB = L(0.85, -0.05, -hz - 0.012);
  ctx.moveTo(doorA[0], doorA[1]);
  ctx.lineTo(doorB[0], doorB[1]);
  ctx.strokeStyle = "rgba(40,48,58,0.55)";
  ctx.stroke();

  const lamp = L(2.0 - nose, -0.18, -hz);
  ctx.fillStyle = driving ? "#fff4cc" : "#f2e2b0";
  ctx.beginPath();
  ctx.arc(lamp[0], lamp[1], 4.5, 0, Math.PI * 2);
  ctx.fill();
  const tail = L(-2.02, -0.22, -hz);
  ctx.fillStyle = !driving && Math.abs(car.vx) > 0.4 ? "#ff5a4a" : "#8e2f32";
  ctx.fillRect(tail[0] - 3, tail[1] - 3, 6, 7);

  ctx.fillStyle = "#e07a2f";
  ctx.font = "bold 11px sans-serif";
  const badge = L(0.15, -0.28, -hz - 0.02);
  ctx.fillText("TEST", badge[0] - 14, badge[1]);

  const spin = car._spin || 0;
  const wy = -CAR_H / 2 + 0.34;
  drawWheel(car.x + -1.32 * c - wy * s, car.y + -1.32 * s + wy * c, car.z - hz * 0.15, 0.34, spin);
  drawWheel(car.x + 1.25 * c - wy * s, car.y + 1.25 * s + wy * c, car.z - hz * 0.15, 0.34, spin);
}

function drawParticles() {
  for (let i = 0; i < particles.length; i++) {
    const p = particles[i];
    const s = worldToScreen(p.x, p.y, p.z);
    const t = 1 - p.age / p.life;
    ctx.fillStyle = "rgba(92,78,70," + (0.35 * t) + ")";
    const r = p.r * SCALE * (0.7 + p.age * 2);
    ctx.beginPath();
    ctx.arc(s[0], s[1], Math.max(1, r), 0, Math.PI * 2);
    ctx.fill();
  }
}

function render() {
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  const sky = ctx.createLinearGradient(0, 0, 0, groundScreen);
  sky.addColorStop(0, "#9eb4c6");
  sky.addColorStop(0.55, "#d5e1ea");
  sky.addColorStop(1, "#efe6d6");
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, viewW, viewH);

  ctx.fillStyle = "rgba(255,255,255,0.45)";
  ctx.beginPath();
  ctx.ellipse(viewW * 0.18, 90, 70, 22, 0, 0, Math.PI * 2);
  ctx.ellipse(viewW * 0.22, 98, 46, 18, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(viewW * 0.72, 70, 90, 24, 0, 0, Math.PI * 2);
  ctx.fill();

  drawGround();

  const order = bodies.filter((b) => b.type === "brick");
  order.sort((a, b) => (-a.x * SIN + a.z * COS) - (-b.x * SIN + b.z * COS));
  for (let i = 0; i < order.length; i++) drawBrick(order[i]);
  drawCar();
  drawParticles();

  const impact = worldToScreen(wallFaceX, 0.02, 0);
  ctx.strokeStyle = "rgba(224, 90, 70, 0.8)";
  ctx.setLineDash([4, 5]);
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(impact[0], impact[1]);
  ctx.lineTo(impact[0], impact[1] - applied.rows * BRICK_H * SCALE - 10);
  ctx.stroke();
  ctx.setLineDash([]);
}

function movingBricks() {
  let n = 0;
  for (let i = 0; i < bodies.length; i++) {
    const b = bodies[i];
    if (b.type !== "brick" || b.sleeping) continue;
    if (Math.hypot(b.vx, b.vy, b.vz) > 0.12 || Math.abs(b.w) > 0.2) n++;
  }
  return n;
}

function updateHud() {
  const speed = Math.hypot(car.vx, car.vy, car.vz);
  ui.telSpeed.textContent = speed.toFixed(2);
  ui.telTime.textContent = simTime.toFixed(2) + " s";
  const moving = phase === "armed" ? 0 : movingBricks();
  ui.telMove.textContent = String(moving);
  ui.telImpact.textContent = impactSpeed == null ? "—" : impactSpeed.toFixed(2);
  let label = "Armed";
  if (phase === "run") {
    if (simTime > 0.4 && speed < 0.15 && moving === 0 && !driving) label = "Settled";
    else if (!driving) label = "Impact";
    else label = "Launch";
  }
  ui.status.textContent = label;
}

function frame(now) {
  if (!lastNow) lastNow = now;
  let dt = (now - lastNow) / 1000;
  lastNow = now;
  if (dt > 0.05) dt = 0.05;
  if (phase === "run") {
    acc += dt;
    const step = 1 / 240;
    const maxSteps = bodies.length > 900 ? 8 : 14;
    let n = 0;
    while (acc >= step && n < maxSteps) {
      substep(step);
      simTime += step;
      acc -= step;
      n++;
    }
    if (n === maxSteps) acc = 0;
    car._spin = (car._spin || 0) + car.vx / 0.34 * dt;
  }
  updateVisuals(dt);
  frameCamera(phase === "run" ? 0.08 : 1);
  render();
  updateHud();
  requestAnimationFrame(frame);
}

