function drawCar() {
  const nose = crumple;
  const c = Math.cos(car.a), s = Math.sin(car.a);
  function L(lx, ly, lz) {
    const wx = car.x + lx * c - ly * s;
    const wy = car.y + lx * s + ly * c;
    return worldToScreen(wx, wy, car.z + lz);
  }
  const hz = car.hz;
  const silhouette = [
    [-2.08, -0.62],
    [-2.02, -0.28],
    [-1.72, -0.18],
    [-1.25, 0.02],
    [-0.72, 0.22],
    [-0.35, 0.48],
    [0.15, 0.62],
    [0.72, 0.58],
    [1.05, 0.28],
    [1.48, 0.08],
    [1.92 - nose, -0.02],
    [2.08 - nose, -0.22],
    [2.02 - nose, -0.55],
    [1.55, -0.62],
    [0.95, -0.62],
    [0.72, -0.5],
    [-0.15, -0.5],
    [-0.55, -0.62],
    [-1.15, -0.62],
    [-1.55, -0.5],
  ];

  function pathSide(z, shift) {
    ctx.beginPath();
    for (let i = 0; i < silhouette.length; i++) {
      const p = L(silhouette[i][0] + shift, silhouette[i][1], z);
      if (i === 0) ctx.moveTo(p[0], p[1]);
      else ctx.lineTo(p[0], p[1]);
    }
    ctx.closePath();
  }

  pathSide(hz, 0);
  ctx.fillStyle = "#9aa3ad";
  ctx.fill();

  const roofA = L(-0.35, 0.48, -hz);
  const roofB = L(0.72, 0.58, -hz);
  const roofC = L(0.72, 0.58, hz);
  const roofD = L(-0.35, 0.48, hz);
  ctx.beginPath();
  ctx.moveTo(roofA[0], roofA[1]);
  ctx.lineTo(roofB[0], roofB[1]);
  ctx.lineTo(roofC[0], roofC[1]);
  ctx.lineTo(roofD[0], roofD[1]);
  ctx.closePath();
  ctx.fillStyle = "#c5ced6";
  ctx.fill();

  const hoodA = L(1.05, 0.28, -hz);
  const hoodB = L(2.05 - nose, -0.08, -hz);
  const hoodC = L(2.05 - nose, -0.08, hz);
  const hoodD = L(1.05, 0.28, hz);
  ctx.beginPath();
  ctx.moveTo(hoodA[0], hoodA[1]);
  ctx.lineTo(hoodB[0], hoodB[1]);
  ctx.lineTo(hoodC[0], hoodC[1]);
  ctx.lineTo(hoodD[0], hoodD[1]);
  ctx.closePath();
  ctx.fillStyle = "#d5dde4";
  ctx.fill();

  pathSide(-hz, 0);
  ctx.fillStyle = "#d7dee6";
  ctx.fill();
  ctx.strokeStyle = "#2c3440";
  ctx.lineWidth = 1.4;
  ctx.stroke();

  ctx.beginPath();
  const win = [[-0.28, 0.18], [0.05, 0.5], [0.62, 0.48], [0.95, 0.2]];
  for (let i = 0; i < win.length; i++) {
    const p = L(win[i][0], win[i][1], -hz - 0.01);
    if (i === 0) ctx.moveTo(p[0], p[1]);
    else ctx.lineTo(p[0], p[1]);
  }
  ctx.closePath();
  ctx.fillStyle = "rgba(70, 110, 130, 0.88)";
  ctx.fill();

  ctx.beginPath();
  const doorA = L(-0.15, -0.08, -hz - 0.012);
  const doorB = L(0.85, -0.05, -hz - 0.012);
  ctx.moveTo(doorA[0], doorA[1]);
  ctx.lineTo(doorB[0], doorB[1]);
  ctx.strokeStyle = "rgba(40,48,58,0.55)";
  ctx.stroke();

  const lamp = L(2.0 - nose, -0.18, -hz);
  ctx.fillStyle = driving ? "#fff4cc" : "#f2e2b0";
  ctx.beginPath();
  ctx.arc(lamp[0], lamp[1], 4.5, 0, Math.PI * 2);
  ctx.fill();
  const tail = L(-2.02, -0.22, -hz);
  ctx.fillStyle = !driving && Math.abs(car.vx) > 0.4 ? "#ff5a4a" : "#8e2f32";
  ctx.fillRect(tail[0] - 3, tail[1] - 3, 6, 7);

  ctx.fillStyle = "#e07a2f";

